function toggleIfExists(id, addHidden) {
const el = document.getElementById(id);
if (!el) return;
el.classList.toggle("hidden", addHidden);
}
async function isUserLoggedIn() {
try {
const res = await fetch("/api/account", { credentials: "same-origin" });
if (!res.ok) return false;
const user = await res.json();
return !!(user && user.email);
} catch (err) {
return false;
}
}
async function updateAuthUI() {
const loggedIn = await isUserLoggedIn();
if (!loggedIn) return;
toggleIfExists("guestPrimaryCta", true);
toggleIfExists("userPrimaryCta", false);
toggleIfExists("guestBottomCta", true);
toggleIfExists("userBottomCta", false);
}
document.querySelectorAll(".trades-link").forEach(function(link) {
link.addEventListener("click", async function(e) {
e.preventDefault();
const loggedIn = await isUserLoggedIn();
if (loggedIn) {
window.location.href = "/trades";
} else {
const premiumTrades = document.getElementById("premium-trades");
if (premiumTrades) {
premiumTrades.scrollIntoView({ behavior: "smooth", block: "start" });
}
}
});
});
const openVideo = document.getElementById("openVideo");
const closeVideo = document.getElementById("closeVideo");
const videoModal = document.getElementById("videoModal");
const tradeVideo = document.getElementById("tradeVideo");
if (openVideo && videoModal) {
openVideo.addEventListener("click", function() {
videoModal.classList.add("show");
if (tradeVideo && typeof tradeVideo.play === "function") {
tradeVideo.play().catch(function() {});
}
});
}
if (closeVideo && videoModal) {
closeVideo.addEventListener("click", function() {
videoModal.classList.remove("show");
if (tradeVideo && typeof tradeVideo.pause === "function") {
tradeVideo.pause();
}
});
}
if (videoModal) {
videoModal.addEventListener("click", function(e) {
if (e.target === videoModal) {
videoModal.classList.remove("show");
if (tradeVideo && typeof tradeVideo.pause === "function") {
tradeVideo.pause();
}
}
});
}
updateAuthUI();
